/// What it takes to break this state, or an unbreakable stand-in for an
/// ID the tables do not know.
pub fn breaking(state: u32) -> Breaking {
    match BREAKING.get(state as usize) {
        Some(b) => *b,
        None => Breaking { hardness: -1.0, needs_tool: true, tool: Tool::None },
    }
}
